sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var gr = new GlideRecord('x_1955226_connecto_connection');
        gr.setLimit(1);
        gr.query();

        if (gr.next()) {
            response.setStatus(200);
            response.setBody({
                success: true,
                data: {
                    sys_id: gr.getUniqueValue(),
                    baseUrl: gr.getValue('base_url'),
                    clientId: gr.getValue('client_id'),
                    clientSecret: gr.getValue('client_secret')
                }
            });
        } else {
            response.setStatus(404);
            response.setBody({
                success: false,
                message: 'Connection not configured'
            });
        }

    } catch (error) {
        response.setStatus(500);
        response.setBody({
            success: false,
            message: error.message
        });
    }
})(request, response);
